def minimum_semesters(n, relations):
    g = [[] for _ in range(n + 1)]
    indeg = [0] * (n + 1)
    for a, b in relations:
        g[a].append(b)
        indeg[b] += 1
    q = [i for i in range(1, n + 1) if indeg[i] == 0]
    sem = done = 0
    while q:
        sem += 1
        nq = []
        for u in q:
            done += 1
            for v in g[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    nq.append(v)
        q = nq
    return sem if done == n else -1

