int minimumSemesters(int n, vector<vector<int>>& rel) {
    vector<vector<int>> g(n + 1); vector<int> indeg(n + 1, 0);
    for (auto& e : rel) { g[e[0]].push_back(e[1]); indeg[e[1]]++; }
    vector<int> q; for (int i = 1; i <= n; i++) if (!indeg[i]) q.push_back(i);
    int sem = 0, done = 0;
    while (!q.empty()) { sem++; vector<int> nq; for (int u : q) { done++; for (int v : g[u]) if (--indeg[v] == 0) nq.push_back(v); } q = nq; }
    return done == n ? sem : -1;
}
